    'gateway_desc_paypal' => 'اقبل المدفوعات في جميع أنحاء العالم باستخدام PayPal — إحدى منصات الدفع عبر الإنترنت الأكثر ثقة والتي تدعم أكثر من 200 دولة وعملات متعددة.',
    'gateway_desc_stripe' => 'قم بمعالجة البطاقات والمحافظ وطرق الدفع المحلية عالميًا باستخدام البنية التحتية القوية للدفع الصديقة للمطورين من Stripe.',
    'gateway_desc_razorpay' => 'بوابة الدفع الرائدة في الهند التي تدعم UPI والبطاقات والخدمات المصرفية عبر الإنترنت والمحافظ وEMI مع تجربة دفع سلسة.',
    'gateway_desc_amazon' => 'اسمح للعملاء بالدفع باستخدام بيانات اعتماد حساب أمازون الخاصة بهم للحصول على تجربة دفع سريعة وموثوقة ومألوفة.',
    'gateway_desc_google' => 'قم بتمكين الدفع السريع والآمن باستخدام Google Pay - الذي يعمل عبر Android وChrome والويب.',
    'gateway_desc_apple' => 'اسمح لمستخدمي أجهزة Apple بالدفع بسرعة وأمان باستخدام Face ID أو Touch ID أو رمز المرور عبر Apple Pay.',
    'gateway_desc_mollie' => 'بوابة دفع أوروبية مرنة تقدم بطاقات iDEAL وBancontact وSEPA والعديد من الطرق المحلية الأخرى.',
    'gateway_desc_paytm' => 'المحفظة الرقمية الشهيرة وبوابة الدفع في الهند التي تدعم UPI والبطاقات والخدمات المصرفية عبر الإنترنت ومحفظة Paytm.',
    'gateway_desc_cashfree' => 'بوابة دفع سريعة وموثوقة للشركات الهندية مع دعم للمدفوعات والاشتراكات والتسويات الفورية.',
    'gateway_desc_instamojo' => 'بوابة دفع بسيطة للشركات الصغيرة والمتوسطة الهندية - يمكنك قبول الدفعات عبر الروابط وواجهة UPI والبطاقات والمحافظ بدون رسوم إعداد.',
    'gateway_desc_flutterwave' => 'منصة دفع لعموم أفريقيا تمكن الشركات من قبول وإرسال المدفوعات عبر أفريقيا وخارجها.',
    'gateway_desc_paystack' => 'بوابة الدفع الرائدة في أفريقيا مع دعم البطاقات والتحويلات المصرفية وUSSD والأموال عبر الهاتف المحمول.',
    'gateway_desc_square' => 'حل تجاري موحد يشمل عمليات الدفع الشخصية وعبر الإنترنت، وإدارة المخزون، وتحليلات الأعمال.',
    'gateway_desc_braintree' => 'خدمة PayPal تقدم عمليات تكامل مرنة للدفع مع دعم البطاقات وPayPal وVenmo والطرق المحلية.',
    'gateway_desc_authorize' => 'إحدى بوابات الدفع الأكثر رسوخًا في الولايات المتحدة، حيث توفر معالجة آمنة للبطاقات واكتشاف الاحتيال.',
    'gateway_desc_ccavenue' => 'أكبر بوابة دفع في الهند مع أكثر من 200 خيار دفع بما في ذلك البطاقات والخدمات المصرفية عبر الإنترنت وواجهة الدفعات الموحدة (UPI) والمحافظ.',
    'gateway_desc_payu' => 'منصة دفع عالمية متواجدة في أكثر من 50 سوقًا، تدعم طرق الدفع المحلية والدولية.',
    'gateway_desc_worldpay' => 'شركة رائدة عالميًا في معالجة الدفع - تقبل البطاقات وطرق الدفع البديلة في 146 دولة.',
    'gateway_desc_klarna' => 'قم بتوفير خطط الشراء الآن والدفع لاحقًا وخطط التقسيط وخيارات التمويل المرنة لتعزيز التحويلات عند الدفع.',
    'gateway_desc_afterpay' => 'اسمح للعملاء بتقسيم المشتريات إلى 4 أقساط بدون فوائد، مما يؤدي إلى زيادة متوسط ​​قيمة الطلب والتحويل.',
